# Descriptive displays only. Original files and sample codes are unchanged.
suppressPackageStartupMessages({library(vegan);library(ggplot2);library(patchwork)})
a<-commandArgs(TRUE);out<-if(length(a))a[1] else 'review_response/storage_integrated_working_v4_2026-10-28'
input<-file.path(out,'storage_inputs');d<-file.path(out,'storage_statistics');f<-file.path(out,'figures');dir.create(f,recursive=TRUE,showWarnings=FALSE)
put<-function(z,n)write.csv(z,file.path(d,paste0(n,'.csv')),row.names=FALSE)
m<-read.csv(file.path(d,'Storage_library_manifest.csv'));metrics<-read.csv(file.path(d,'Storage_library_metrics.csv'));groupmeans<-read.csv(file.path(d,'Storage_equal_woman_group_means.csv'));den<-read.csv(file.path(d,'Storage_group_denominators.csv'))
for(arm in c('baseline_39','sensitivity_41')){
 x<-read.csv(file.path(input,paste0(arm,'_source_counts.csv')),row.names=1,check.names=FALSE);stopifnot(identical(colnames(x),m$SourceCode));pr<-t(as.matrix(x));pr<-pr/rowSums(pr)
 py<-metrics[metrics$taxon_arm==arm,];py<-py[match(rownames(pr),py$SourceCode),]
 stopifnot(max(abs(diversity(pr,index='shannon')-py$Shannon))<1e-12,max(abs(diversity(pr,index='simpson')-py$Simpson_1_minus_D))<1e-12,identical(as.numeric(rowSums(pr>0)),as.numeric(py$Richness)))
 even<-diversity(pr)/log(rowSums(pr>0));even[rowSums(pr>0)<2]<-NA
 stopifnot(isTRUE(all.equal(even,py$Pielou_evenness,check.attributes=FALSE,tolerance=1e-12)))
 # Verify summaries and group means in R without using Python summary values.
 tx<-read.csv(file.path(input,'original_taxonomy.csv'));names(tx)[1]<-'Taxon';genus<-tx$Genus[match(colnames(pr),tx$Taxon)]
 stopifnot(max(abs(100*rowSums(pr[,genus=='Lactobacillus',drop=FALSE])-py$Lactobacillus_genus_pct))<1e-10)
 for(site in unique(m$Location))for(frac in unique(m$Fraction))for(s in c('FRESH','FROZEN')){
  z<-m[m$Location==site&m$Fraction==frac&m$Storage==s,];g<-groupmeans[groupmeans$taxon_arm==arm&groupmeans$Location==site&groupmeans$Fraction==frac&groupmeans$Storage==s,];g<-g[match(colnames(pr),g$Taxon),]
  means<-sapply(split(z$SourceCode,z$Participant),function(n)colMeans(pr[n,,drop=FALSE]));stopifnot(max(abs(rowMeans(means)-g$mean_relative_abundance))<1e-12)
 }
}
writeLines('PASS: vegan independently verifies all298 library Shannon/Simpson/richness/evenness/Lactobacillus metrics and all equal-woman storage-group profiles from39/41 count inputs. No hypothesis or equivalence tests performed.',file.path(d,'Independent_R_storage_verification.txt'))
sitelevels<-c('VAGINA','CERVIX','ENDOMETRIUM');sites<-c('Vagina','Cervix','Endometrium');fractions<-c('PRE','IgA','IgM','IgG')
fmt<-function(z){z$Location<-factor(z$Location,levels=sitelevels,labels=sites);z$Fraction<-factor(z$Fraction,levels=fractions);if('Storage'%in%names(z))z$Storage<-factor(z$Storage,levels=c('FRESH','FROZEN'),labels=c('Fresh','Frozen'));z}
cols<-c(Fresh='#D97B31',Frozen='#3A79B8');theme<-theme_bw(base_size=14)+theme(legend.position='bottom',panel.grid.minor=element_blank(),strip.background=element_rect(fill='grey94'),plot.caption=element_text(size=11,hjust=0))
savefig<-function(p,name,w,h){ggsave(file.path(f,paste0(name,'.png')),p,width=w,height=h,dpi=300,bg='white');ggsave(file.path(f,paste0(name,'.pdf')),p,width=w,height=h,bg='white')}
z<-metrics[metrics$taxon_arm=='baseline_39'&metrics$Fraction!='IgG',];z<-fmt(z)
n<-fmt(den[den$Fraction!='IgG',]);n$label<-paste0('n=',n$n_women)
p7a<-ggplot(z,aes(Fraction,Lactobacillus_genus_pct,colour=Storage))+geom_boxplot(position=position_dodge(.7),width=.55,outlier.shape=NA,fill=NA,linewidth=.4)+geom_point(position=position_jitterdodge(jitter.width=.14,dodge.width=.7,seed=20261028),size=1.7,alpha=.85)+geom_text(data=n,aes(y=106,label=label),position=position_dodge(.7),size=3.2)+facet_wrap(~Location,nrow=1)+scale_colour_manual(values=cols)+coord_cartesian(ylim=c(0,110))+scale_y_continuous(breaks=c(0,25,50,75,100))+theme+labs(x=NULL,y='Lactobacillus abundance (%)',colour='Recorded storage')
gm<-groupmeans[groupmeans$taxon_arm=='baseline_39'&groupmeans$Fraction!='IgG',];selection<-aggregate(gm$mean_relative_abundance,list(Taxon=gm$Taxon),mean);names(selection)[2]<-'mean_across_18_group_profiles';selection<-selection[order(-selection$mean_across_18_group_profiles,selection$Taxon),];selection$displayed_in_Figure7<-seq_len(nrow(selection))<=8;put(selection,'Figure7_heatmap_taxon_selection')
h<-gm[gm$Taxon%in%selection$Taxon[1:8],];put(h,'Figure7_heatmap_source_values');h<-fmt(h);h$Taxon<-factor(h$Taxon,levels=rev(selection$Taxon[1:8]));h$group<-factor(paste(h$Fraction,h$Storage,sep='\n'),levels=as.vector(t(outer(fractions[1:3],c('Fresh','Frozen'),paste,sep='\n'))))
p7b<-ggplot(h,aes(group,Taxon,fill=100*mean_relative_abundance))+geom_tile(colour='white',linewidth=.3)+facet_wrap(~Location,nrow=1)+scale_fill_gradientn(colours=c('#fff4df','#f49b4a','#a9231c'),limits=c(0,100))+theme+theme(axis.text.x=element_text(size=10),axis.text.y=element_text(size=11))+labs(x='Fraction and recorded storage',y=NULL,fill='Mean abundance (%)')
p7<-(p7a/p7b)+plot_layout(heights=c(.9,1.1))+plot_annotation(tag_levels='A',caption='Descriptive retained sequencing data, not preservation validation. The cervical frozen groups contain two women.\nOne woman contributes both endometrial storage preparations; storage conditions are otherwise represented by different women.')
savefig(p7,'Figure7_descriptive_storage',13,10.2)
# S2: retain the four descriptive alpha metrics, removing independent-group tests.
z<-metrics[metrics$taxon_arm=='baseline_39',];long<-do.call(rbind,lapply(c('Shannon','Simpson_1_minus_D','Richness','Pielou_evenness'),function(v)data.frame(z[,c('SourceCode','Participant','Location','Fraction','Storage')],metric=v,value=z[[v]])));long<-fmt(long);long$metric<-factor(long$metric,levels=c('Shannon','Simpson_1_minus_D','Richness','Pielou_evenness'),labels=c('Shannon H','Simpson (1-D)','Retained taxon richness','Pielou evenness'));put(long,'FigureS2_alpha_plotted_values')
p2<-ggplot(long,aes(Fraction,value,colour=Storage))+geom_boxplot(position=position_dodge(.7),width=.55,outlier.shape=NA,fill=NA,linewidth=.35)+geom_point(position=position_jitterdodge(jitter.width=.14,dodge.width=.7,seed=20261028),size=1.25,alpha=.75)+facet_grid(metric~Location,scales='free_y')+scale_colour_manual(values=cols)+theme+theme(strip.text.y=element_text(size=11))+labs(x='Retained library fraction',y=NULL,colour='Recorded storage',caption='All 149 libraries from 15 women and 40 preparations. Boxes summarize observed library values; dots show every available library.\nPielou evenness is undefined for six one-taxon libraries; missing values are counted in the tables.\nThese are descriptive distributions, not independent storage replications. No p-values or equivalence claims.')
savefig(p2,'FigureS2_storage_alpha_descriptive',12,10.5)
# S7: group-average composition is not paired agreement. No taxon-level p-values.
wide<-reshape(groupmeans[groupmeans$taxon_arm=='baseline_39',c('Location','Fraction','Taxon','Storage','mean_relative_abundance')],idvar=c('Location','Fraction','Taxon'),timevar='Storage',direction='wide');put(wide,'FigureS7_group_mean_source_values');wide<-fmt(wide)
p7s<-ggplot(wide,aes(100*mean_relative_abundance.FRESH,100*mean_relative_abundance.FROZEN))+geom_abline(slope=1,intercept=0,colour='grey65',lty=2)+geom_point(size=1.2,alpha=.65,colour='#4a6274')+facet_grid(Fraction~Location)+scale_x_sqrt(breaks=c(0,1,4,16,64,100))+scale_y_sqrt(breaks=c(0,1,4,16,64,100))+coord_cartesian(xlim=c(0,100),ylim=c(0,100))+theme+labs(x='Fresh equal-woman mean abundance (%) on square-root scale',y='Frozen equal-woman mean abundance (%) on square-root scale',caption='Each dot is one provisional assignment in the 39-taxon set; dashed line marks equality of the displayed group means.\nTaxa are not independent storage replicates. Between-woman group averages do not measure preservation or paired agreement.')
savefig(p7s,'FigureS7_storage_group_means',11.5,10)
# S15: common PRE-only descriptive ordination. No ellipses or hypothesis tests.
x<-read.csv(file.path(input,'baseline_39_source_counts.csv'),row.names=1,check.names=FALSE);pre<-m[m$Fraction=='PRE',];rel<-t(as.matrix(x[,pre$SourceCode]));rel<-rel/rowSums(rel);bc<-vegdist(rel,method='bray');ord<-wcmdscale(bc,k=2,eig=TRUE,add='lingoes');stopifnot(nrow(ord$points)==37)
co<-data.frame(pre,Axis1=ord$points[,1],Axis2=ord$points[,2]);put(co,'FigureS15_PRE_PCoA_coordinates');put(data.frame(SourceCode=rownames(as.matrix(bc)),as.matrix(bc),check.names=FALSE),'FigureS15_PRE_Bray_matrix');put(data.frame(index=seq_along(ord$eig),eigenvalue=ord$eig),'FigureS15_PRE_PCoA_eigenvalues');write.csv(data.frame(Lingoes_additive_constant=ord$ac,positive_eigenvalue_sum=sum(ord$eig[ord$eig>0])),file.path(d,'FigureS15_PRE_PCoA_parameters.csv'),row.names=FALSE)
pc<-100*ord$eig[1:2]/sum(ord$eig[ord$eig>0]);co<-fmt(co);pt99<-co[co$Participant==99&co$Location=='Endometrium',]
p15<-ggplot(co,aes(Axis1,Axis2,colour=Storage))+geom_point(size=2.2,alpha=.85)+geom_path(data=pt99,aes(group=Participant),linetype=2,colour='grey50',linewidth=.5)+geom_text(data=pt99,aes(label=SourceCode),size=3,nudge_y=.025,show.legend=FALSE)+facet_wrap(~Location,nrow=1)+scale_colour_manual(values=cols)+theme+labs(x=sprintf('PRE PCoA1 (%.1f%% of positive corrected eigenvalues)',pc[1]),y=sprintf('PRE PCoA2 (%.1f%%)',pc[2]),colour='Recorded storage',caption='One common Bray-Curtis PCoA of 37 PRE libraries, with Lingoes correction, displayed on common axes across sites.\nThe dashed line joins two recorded endometrial preparations from woman 99, without establishing split aliquots. No storage test or confidence ellipse.')
savefig(p15,'FigureS15_PRE_storage_ordination',12,5.2)
# S19 replaces an unsupported equivalence verdict with the observed n=1
# woman's measurements. Four fractions do not create four storage replicates.
z<-metrics[metrics$taxon_arm=='baseline_39'&metrics$Participant==99&metrics$Location=='ENDOMETRIUM',];pair<-do.call(rbind,lapply(c('Shannon','Lactobacillus_genus_pct'),function(v)data.frame(z[,c('SourceCode','Participant','Location','Fraction','Storage')],metric=v,value=z[[v]])));pair<-fmt(pair);pair$metric<-factor(pair$metric,levels=c('Shannon','Lactobacillus_genus_pct'),labels=c('Shannon H','Lactobacillus abundance (%)'));put(pair,'FigureS19_participant99_plotted_values')
p19<-ggplot(pair,aes(Storage,value,group=1))+geom_line(colour='grey50',linetype=2,linewidth=.5)+geom_point(aes(colour=Storage),size=2.5)+facet_grid(metric~Fraction,scales='free_y')+scale_colour_manual(values=cols)+theme+theme(legend.position='none',strip.text.y=element_text(size=11))+labs(x='Recorded preparation condition',y=NULL,caption='Participant 99 endometrium only: one woman, two preparations, four available fractions per preparation.\nThese lines connect records from the same woman; they do not establish verified split aliquots or independent storage replicates. No equivalence test.')
savefig(p19,'FigureS19_two_preparation_description',12,6.8)
capture.output(sessionInfo(),file=file.path(f,'Storage_R_sessionInfo.txt'))
cat('Five descriptive PNG/PDF pairs created; independent R metric/profile checks PASS.\n')
